    fun get(language: String, key: String): String =
        extraStrings[language]?.get(key) ?: strings[language]?.get(key) ?: extraStrings.getValue("hi").getValue(key)

    fun missingKeys(language: String): Set<String> {
        val required = strings.getValue("hi").keys + extraStrings.getValue("hi").keys
        val available = (strings[language]?.keys ?: emptySet()) + (extraStrings[language]?.keys ?: emptySet())
        return required - available
    }
